// Cloudflare entry for the web app: wraps the OpenNext worker and sends API traffic
// (REST, uploaded images, Socket.IO) over a service binding, so the whole shop is one origin
// and the refresh-token cookie stays first-party.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as nextHandler } from '../.open-next/worker.js';

interface Env {
  API: Fetcher;
  ASSETS: Fetcher;
}

const API_PREFIXES = ['/api/v1/', '/uploads/', '/socket.io/'];

function toApi(request: Request, env: Env, url: URL) {
  const headers = new Headers(request.headers);
  // the API rate-limits by this header; never trust what the browser sent
  headers.set('x-forwarded-for', request.headers.get('cf-connecting-ip') ?? 'unknown');
  return env.API.fetch(new Request(url, new Request(request, { headers })));
}

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext) {
    const url = new URL(request.url);
    if (API_PREFIXES.some((p) => url.pathname.startsWith(p))) return toApi(request, env, url);

    // The image optimizer only reads static assets; uploaded photos come from the API as-is.
    const src = url.pathname === '/_next/image' ? url.searchParams.get('url') : null;
    if (src?.startsWith('/uploads/')) return toApi(request, env, new URL(src, url));

    return nextHandler.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<Env>;
